import 'package:stripe_sdk/stripe_sdk.dart';
import 'package:shopapp/data/models/payment.dart';

class StripePaymentGateway {
  final StripeClient client;

  StripePaymentGateway({required this.client});

  Future<Payment> submit(double amount) async {
    var intent = await client.createIntent(amount);
    return Payment.fromMap(intent.data());
  }
}

class Payment {
  final String id;
  final double amount;
  final String status;

  Payment({required this.id, required this.amount, required this.status});

  factory Payment.fromMap(Map<String, dynamic> map) {
    return Payment(id: map['id'], amount: map['amount'], status: map['status']);
  }
}

import 'package:shopapp/data/gateways/stripe_payment_gateway.dart';
import 'package:shopapp/data/models/payment.dart';
import 'package:shopapp/domain/repositories/payment_repository.dart';

class PaymentRepositoryImpl implements PaymentRepository {
  final StripePaymentGateway gateway;

  PaymentRepositoryImpl(this.gateway);

  @override
  Future<Payment> charge(double amount) {
    return gateway.submit(amount);
  }
}

import 'package:shopapp/data/models/payment.dart';

abstract class PaymentRepository {
  Future<Payment> charge(double amount);
}

import 'package:shopapp/data/models/payment.dart';
import 'package:shopapp/domain/repositories/payment_repository.dart';

class SubmitPayment {
  final PaymentRepository repository;

  SubmitPayment(this.repository);

  Future<Payment> call(double amount) async {
    return await repository.charge(amount);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:stripe_sdk/stripe_sdk.dart';
import 'package:shopapp/stripe_options.dart';
import 'package:shopapp/service_locator.dart';
import 'package:shopapp/presentation/bloc/payment_bloc.dart';
import 'package:shopapp/presentation/bloc/payment_event.dart';
import 'package:shopapp/presentation/pages/checkout_screen.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Stripe.initialize(options: DefaultStripeOptions.currentPlatform);
  initLocator();
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (_) => getIt<PaymentBloc>()..add(SubmitPressed()),
      child: MaterialApp(home: CheckoutScreen()),
    );
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:shopapp/domain/usecases/submit_payment.dart';
import 'package:shopapp/presentation/bloc/payment_event.dart';
import 'package:shopapp/presentation/bloc/payment_state.dart';

class PaymentBloc extends Bloc<PaymentEvent, PaymentState> {
  final SubmitPayment submitPayment;

  PaymentBloc({required this.submitPayment}) : super(PaymentPending()) {
    on<SubmitPressed>((event, emit) async {
      emit(PaymentPending());
      try {
        final payment = await submitPayment.call(10.0);
        emit(PaymentSuccess(payment));
      } catch (e) {
        emit(PaymentFailed(e.toString()));
      }
    });
  }
}

import 'package:shopapp/data/models/payment.dart';

abstract class PaymentState {}

class PaymentPending extends PaymentState {}

class PaymentSuccess extends PaymentState {
  final Payment payment;
  PaymentSuccess(this.payment);
}

class PaymentFailed extends PaymentState {
  final String message;
  PaymentFailed(this.message);
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:shopapp/presentation/bloc/payment_bloc.dart';
import 'package:shopapp/presentation/bloc/payment_state.dart';
import 'package:shopapp/presentation/widgets/receipt_card.dart';

class CheckoutScreen extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Checkout')),
      body: BlocBuilder<PaymentBloc, PaymentState>(
        builder: (context, state) {
          if (state is PaymentPending) {
            return Center(child: CircularProgressIndicator());
          } else if (state is PaymentSuccess) {
            return ReceiptCard(payment: state.payment);
          } else if (state is PaymentFailed) {
            return Center(child: Text('error : ${state.message}'));
          }
          return Container();
        },
      ),
    );
  }
}

