import 'package:get_it/get_it.dart';
import 'package:stripe_sdk/stripe_sdk.dart';
import 'package:shopapp/data/gateways/stripe_payment_gateway.dart';
import 'package:shopapp/data/repositories/payment_repository_impl.dart';
import 'package:shopapp/domain/repositories/payment_repository.dart';
import 'package:shopapp/domain/usecases/submit_payment.dart';
import 'package:shopapp/presentation/bloc/payment_bloc.dart';

GetIt getIt = GetIt.instance;

void initLocator() {
  getIt.registerLazySingleton<StripeClient>(() => StripeClient.instance);
  getIt.registerLazySingleton<StripePaymentGateway>(
      () => StripePaymentGateway(client: getIt<StripeClient>()));
  getIt.registerLazySingleton<PaymentRepository>(
      () => PaymentRepositoryImpl(getIt<StripePaymentGateway>()));
  getIt.registerLazySingleton<SubmitPayment>(
      () => SubmitPayment(getIt<PaymentRepository>()));
  getIt.registerFactory(() => PaymentBloc(submitPayment: getIt<SubmitPayment>()));
}

